def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    if n == 1:
        return 'C'
    if n < 5:
        return 'C' if opp[-1] == 'C' else 'D'
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    recent = opp[-6:]
    rec_c = sum(1 for x in recent if x == 'C')
    rec_len = len(recent)
    last_me = me[-1]
    last_opp = opp[-1]

    if opp_d == 0:
        if rng.random() < 0.08:
            return 'D'
        return 'C'
    if opp_c == 0:
        return 'D'
    if rec_c == rec_len:
        if opp_d >= 4 and rng.random() < 0.15:
            return 'D'
        return 'C'
    if rec_c <= 1:
        if last_opp == 'C' and rng.random() < 0.2:
            return 'C'
        return 'D'
    if last_opp == 'D':
        if opp_d * 5 > n * 3:
            return 'D'
        if last_me == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if rng.random() < 0.35:
            return 'C'
        return 'D'
    if opp_c * 100 < n * 40:
        return 'D'
    if rng.random() < 0.1:
        return 'D'
    return 'C'
